#!/bin/bash
# Burn subtitles into the 720p stitched blank-tab video, then upscale is a separate step.
# Usage: subtitle-burn-blank-tab.sh <input-720p.mp4> <output-720p-subtitled.mp4>
set -e
ffmpeg -y -v error -i "$1" -vf "drawtext=fontfile=/home/hatch/workspace/clothing-explained/fonts/TikTokSans-Bold.ttf:text='Your red tab on':fontsize=42:fontcolor=white:x=(w-text_w)/2:y=512:enable='between(t,0.0,1.27)',drawtext=fontfile=/home/hatch/workspace/clothing-explained/fonts/TikTokSans-Bold.ttf:text='your jeans is blank':fontsize=42:fontcolor=white:x=(w-text_w)/2:y=512:enable='between(t,1.27,2.54)',drawtext=fontfile=/home/hatch/workspace/clothing-explained/fonts/TikTokSans-Bold.ttf:text='on purpose, why?':fontsize=42:fontcolor=white:x=(w-text_w)/2:y=512:enable='between(t,2.54,3.49)',drawtext=fontfile=/home/hatch/workspace/clothing-explained/fonts/TikTokSans-Bold.ttf:text='In 1936 Levi’s sewed':fontsize=42:fontcolor=white:x=(w-text_w)/2:y=512:enable='between(t,4.33,5.56)',drawtext=fontfile=/home/hatch/workspace/clothing-explained/fonts/TikTokSans-Bold.ttf:text='a red cloth tab':fontsize=42:fontcolor=white:x=(w-text_w)/2:y=512:enable='between(t,5.56,6.79)',drawtext=fontfile=/home/hatch/workspace/clothing-explained/fonts/TikTokSans-Bold.ttf:text='into the back':fontsize=42:fontcolor=white:x=(w-text_w)/2:y=512:enable='between(t,6.79,7.72)',drawtext=fontfile=/home/hatch/workspace/clothing-explained/fonts/TikTokSans-Bold.ttf:text='pocket seam.':fontsize=42:fontcolor=white:x=(w-text_w)/2:y=512:enable='between(t,7.72,8.33)',drawtext=fontfile=/home/hatch/workspace/clothing-explained/fonts/TikTokSans-Bold.ttf:text='Levi’s registered the tab’s':fontsize=42:fontcolor=white:x=(w-text_w)/2:y=512:enable='between(t,8.96,10.12)',drawtext=fontfile=/home/hatch/workspace/clothing-explained/fonts/TikTokSans-Bold.ttf:text='shape and placement, so':fontsize=42:fontcolor=white:x=(w-text_w)/2:y=512:enable='between(t,10.12,11.27)',drawtext=fontfile=/home/hatch/workspace/clothing-explained/fonts/TikTokSans-Bold.ttf:text='a copycat with a':fontsize=42:fontcolor=white:x=(w-text_w)/2:y=512:enable='between(t,11.27,12.43)',drawtext=fontfile=/home/hatch/workspace/clothing-explained/fonts/TikTokSans-Bold.ttf:text='different name can':fontsize=42:fontcolor=white:x=(w-text_w)/2:y=512:enable='between(t,12.43,13.3)',drawtext=fontfile=/home/hatch/workspace/clothing-explained/fonts/TikTokSans-Bold.ttf:text='still infringe.':fontsize=42:fontcolor=white:x=(w-text_w)/2:y=512:enable='between(t,13.3,13.88)',drawtext=fontfile=/home/hatch/workspace/clothing-explained/fonts/TikTokSans-Bold.ttf:text='A trademark can be':fontsize=42:fontcolor=white:x=(w-text_w)/2:y=512:enable='between(t,14.57,15.58)',drawtext=fontfile=/home/hatch/workspace/clothing-explained/fonts/TikTokSans-Bold.ttf:text='lost if unused for':fontsize=42:fontcolor=white:x=(w-text_w)/2:y=512:enable='between(t,15.58,16.6)',drawtext=fontfile=/home/hatch/workspace/clothing-explained/fonts/TikTokSans-Bold.ttf:text='more than five years,':fontsize=42:fontcolor=white:x=(w-text_w)/2:y=512:enable='between(t,16.6,17.61)',drawtext=fontfile=/home/hatch/workspace/clothing-explained/fonts/TikTokSans-Bold.ttf:text='because it can':fontsize=42:fontcolor=white:x=(w-text_w)/2:y=512:enable='between(t,17.61,18.38)',drawtext=fontfile=/home/hatch/workspace/clothing-explained/fonts/TikTokSans-Bold.ttf:text='be cancelled.':fontsize=42:fontcolor=white:x=(w-text_w)/2:y=512:enable='between(t,18.38,18.88)',drawtext=fontfile=/home/hatch/workspace/clothing-explained/fonts/TikTokSans-Bold.ttf:text='So Levi’s puts a':fontsize=42:fontcolor=white:x=(w-text_w)/2:y=512:enable='between(t,19.52,20.74)',drawtext=fontfile=/home/hatch/workspace/clothing-explained/fonts/TikTokSans-Bold.ttf:text='blank tab, only the':fontsize=42:fontcolor=white:x=(w-text_w)/2:y=512:enable='between(t,20.74,21.96)',drawtext=fontfile=/home/hatch/workspace/clothing-explained/fonts/TikTokSans-Bold.ttf:text='registered mark, no name,':fontsize=42:fontcolor=white:x=(w-text_w)/2:y=512:enable='between(t,21.96,23.17)',drawtext=fontfile=/home/hatch/workspace/clothing-explained/fonts/TikTokSans-Bold.ttf:text='on about one':fontsize=42:fontcolor=white:x=(w-text_w)/2:y=512:enable='between(t,23.17,24.09)',drawtext=fontfile=/home/hatch/workspace/clothing-explained/fonts/TikTokSans-Bold.ttf:text='in ten products.':fontsize=42:fontcolor=white:x=(w-text_w)/2:y=512:enable='between(t,24.09,25.0)',drawtext=fontfile=/home/hatch/workspace/clothing-explained/fonts/TikTokSans-Bold.ttf:text='That blank tab proves':fontsize=42:fontcolor=white:x=(w-text_w)/2:y=512:enable='between(t,25.6,26.92)',drawtext=fontfile=/home/hatch/workspace/clothing-explained/fonts/TikTokSans-Bold.ttf:text='the shape is in':fontsize=42:fontcolor=white:x=(w-text_w)/2:y=512:enable='between(t,26.92,28.23)',drawtext=fontfile=/home/hatch/workspace/clothing-explained/fonts/TikTokSans-Bold.ttf:text='use, so Levi’s can':fontsize=42:fontcolor=white:x=(w-text_w)/2:y=512:enable='between(t,28.23,29.54)',drawtext=fontfile=/home/hatch/workspace/clothing-explained/fonts/TikTokSans-Bold.ttf:text='still sue imitators.':fontsize=42:fontcolor=white:x=(w-text_w)/2:y=512:enable='between(t,29.54,30.53)'" -c:v libx264 -crf 18 -preset veryfast -c:a copy "$2"
ffprobe -v error -show_entries format=duration -of csv=p=0 "$2"
